package com.narudzbine.identity.application;

import static org.assertj.core.api.Assertions.*;
import com.narudzbine.shared.api.UuidGenerator;
import com.narudzbine.shared.infrastructure.database.MigrationCommand;
import java.nio.file.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.testcontainers.junit.jupiter.*;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.testcontainers.utility.DockerImageName;

@Testcontainers
class CapabilityRetentionIT {
 @Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:74935e72241653ca55e0414067e6d8763aceb8a810eb51b452253ec3dcfc4336").asCompatibleSubstituteFor("postgres"));
 static final Instant NOW=Instant.parse("2026-10-21T12:00:00Z"),CUTOFF=NOW.minus(Duration.ofDays(30));
 static final UuidGenerator IDS=new UuidGenerator(Clock.fixed(NOW,ZoneOffset.UTC));
 static JdbcTemplate owner;static DriverManagerDataSource runtime;static UUID admin,reviewer,business,org,session;
 CapabilityRetention service;TransactionTemplate tx;
 enum Family{EXCHANGE,FLOW,RECOVERY}
 record Row(Family family,UUID id){}
 @BeforeAll static void schema()throws Exception{
  MigrationCommand.migrate(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());var ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());owner=new JdbcTemplate(ds);admin=IDS.next();reviewer=IDS.next();business=IDS.next();org=IDS.next();session=IDS.next();
  new TransactionTemplate(new DataSourceTransactionManager(ds)).executeWithoutResult(t->{owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES(?,'PLATFORM_ADMIN',?,true,'Synthetic','ACTIVE'),(?,'PLATFORM_ADMIN',?,true,'Synthetic','ACTIVE'),(?,'BUSINESS',?,true,'Synthetic','ACTIVE')",admin,admin+"@example.com",reviewer,reviewer+"@example.com",business,business+"@example.com");owner.update("INSERT INTO platform_account(id) VALUES(?),(?)",admin,reviewer);owner.update("INSERT INTO organization(id,type,country,currency,display_name,legal_name,registration_identifier,address_line1,address_city,address_postal_code,address_country,default_language,state,owner_account_id) VALUES(?,'BUYER','RS','RSD','Synthetic','Synthetic','SYN','Synthetic','Synthetic','11000','RS','sr-Latn-RS','ACTIVE',?)",org,business);owner.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,'OWNER')",business,org);});
  owner.update("INSERT INTO application_session(id,account_id,transport,token_hash,device_label,created_at,last_qualified_activity_at,absolute_expires_at,auth_at,auth_method_type,credential_generation,security_epoch) VALUES(?,?,'NATIVE',?,'Synthetic',?,?,?,?,'PASSWORD',0,0)",session,admin,hash(session),at(CUTOFF.minusSeconds(86400)),at(CUTOFF.minusSeconds(86400)),at(CUTOFF),at(CUTOFF.minusSeconds(86400)));
  owner.execute("CREATE ROLE capability_runtime LOGIN PASSWORD 'synthetic-local-only'");owner.execute("GRANT USAGE ON SCHEMA public TO capability_runtime");owner.execute("GRANT SELECT ON external_exchange,external_challenge,recovery_case,recovery_delivery,email_change,credential_operation,external_delivery_retention_blocker TO capability_runtime");owner.execute(Files.readString(Path.of("retention/capability-grants.sql")).replace("__RUNTIME_ROLE__","capability_runtime"));runtime=new DriverManagerDataSource(DB.getJdbcUrl(),"capability_runtime","synthetic-local-only");
 }
 static Timestamp at(Instant i){return Timestamp.from(i);}
 static byte[] hash(UUID id){try{return java.security.MessageDigest.getInstance("SHA-256").digest(id.toString().getBytes(java.nio.charset.StandardCharsets.US_ASCII));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 @BeforeEach void service(){service=new CapabilityRetention(new JdbcTemplate(runtime),Clock.fixed(NOW,ZoneOffset.UTC));tx=new TransactionTemplate(new DataSourceTransactionManager(runtime));tx.setTimeout(10);for(Family f:Family.values())for(int attempt=0;attempt<5;attempt++){if(sweep(f)!=1000)break;}}
 int sweep(Family f){return tx.execute(t->switch(f){case EXCHANGE->service.exchange();case FLOW->service.flow();case RECOVERY->service.recovery();});}
 Row flow(Instant expiry,String transport,String purpose,String state,boolean verifier){UUID id=IDS.next();boolean login=purpose.equals("LOGIN"),browser=transport.equals("BROWSER");owner.update("INSERT INTO external_challenge(id,state_hash,provider,purpose,transport,return_target,native_challenge,browser_binding_hash,encrypted_verifier,account_id,original_session_id,original_token_hash,security_epoch,credential_generation,state,created_at,expires_at) VALUES(?,?,'GOOGLE',?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,hash(id),purpose,transport,browser?"WEB":"ANDROID",browser?null:"a".repeat(43),browser?hash(IDS.next()):null,new byte[71],login?null:admin,login?null:session,login?null:hash(session),login?null:0L,login?null:0L,state,at(expiry.minusSeconds(300)),at(expiry));if(!verifier)owner.update("UPDATE external_challenge SET encrypted_verifier=NULL WHERE id=?",id);return new Row(Family.FLOW,id);}
 Row exchange(Instant expiry,Instant consumed,boolean verifier){Row parent=flow(expiry,"NATIVE","LOGIN","COMPLETED",true);owner.update("INSERT INTO external_exchange(code_hash,challenge_id,account_id,identity_id,issuer,subject,security_epoch,credential_generation,authenticated_at,expires_at,consumed_at) VALUES(?,?,?,NULL,'https://synthetic.example','synthetic-subject',0,0,?,?,?)",hash(IDS.next()),parent.id,admin,at(expiry.minusSeconds(60)),at(expiry),consumed==null?null:at(consumed));if(!verifier)owner.update("UPDATE external_challenge SET encrypted_verifier=NULL WHERE id=?",parent.id);return new Row(Family.EXCHANGE,parent.id);}
 Row recovery(Instant expiry,String state,Instant updated,boolean source){UUID id=IDS.next();Instant created=expiry.minusSeconds(8*86400);owner.update("INSERT INTO recovery_case(id,creator_id,creator_epoch,reviewer_id,reviewer_epoch,organization_id,target_id,former_owner_id,target_epoch,target_generation,owner_epoch,owner_generation,kind,old_email,new_email,reason,evidence_reference,request_digest,state,token_hash,created_at,not_before,expires_at,updated_at) VALUES(?,?,0,?,0,?,?,?,0,0,0,0,'EMAIL',?,?,'Synthetic','synthetic/evidence',?,?,?,?,?,?,?)",id,admin,reviewer,org,business,business,business+"@example.com",id+"@example.com",hash(id),state,hash(IDS.next()),at(created),at(created.plusSeconds(86400)),at(expiry),at(updated));UUID delivery=IDS.next();owner.update("INSERT INTO recovery_delivery(id,case_id,kind,recipient_id,destination_email,encrypted_token,locale,state,created_at) VALUES(?,?,'ACCEPTANCE',?,?,?,'en','QUEUED',?)",delivery,id,business,business+"@example.com",new byte[71],at(created));if(!source)owner.update("UPDATE recovery_delivery SET encrypted_token=NULL WHERE id=?",delivery);return new Row(Family.RECOVERY,id);}
 Row row(Family f,Instant expiry){return switch(f){case EXCHANGE->exchange(expiry,null,false);case FLOW->flow(expiry,"BROWSER","LINK","OPEN",false);case RECOVERY->recovery(expiry,"NOTICE_PERIOD",expiry.minusSeconds(1),false);};}
 String table(Family f){return switch(f){case EXCHANGE->"external_exchange";case FLOW->"external_challenge";case RECOVERY->"recovery_case";};}
 String key(Family f){return f==Family.EXCHANGE?"challenge_id":"id";}
 String field(Family f){return f==Family.EXCHANGE?"code_hash":f==Family.FLOW?"state_hash":"token_hash";}
 boolean present(Row r){return owner.queryForObject("SELECT "+field(r.family)+" IS NOT NULL FROM "+table(r.family)+" WHERE "+key(r.family)+"=?",Boolean.class,r.id);}
 String metadata(Row r){String excluded=r.family==Family.EXCHANGE?"ARRAY['code_hash']":r.family==Family.FLOW?"ARRAY['state_hash','browser_binding_hash','original_token_hash','native_challenge']":"ARRAY['token_hash','acceptance_retired']";return owner.queryForObject("SELECT(to_jsonb(p)-"+excluded+")::text FROM "+table(r.family)+" p WHERE "+key(r.family)+"=?",String.class,r.id);}
 @Test void inclusiveThirtyDayCutoffPreservesAllOriginalSourceMetadata(){for(Family f:Family.values()){var exact=row(f,CUTOFF);var fresh=row(f,CUTOFF.plusMillis(1));String before=metadata(exact);assertThat(sweep(f)).isEqualTo(1);assertThat(present(exact)).isFalse();assertThat(present(fresh)).isTrue();assertThat(metadata(exact)).isEqualTo(before);assertThat(sweep(f)).isZero();if(f==Family.EXCHANGE)sweep(Family.FLOW);}}
 @Test void browserNativeAndAllPurposesRetireOnlyBindings(){for(String transport:List.of("BROWSER","NATIVE"))for(String purpose:List.of("LOGIN","LINK","REAUTHENTICATE")){var r=flow(CUTOFF,transport,purpose,"OPEN",false);String before=metadata(r);assertThat(sweep(Family.FLOW)).isEqualTo(1);assertThat(owner.queryForObject("SELECT state_hash IS NULL AND browser_binding_hash IS NULL AND original_token_hash IS NULL AND native_challenge IS NULL FROM external_challenge WHERE id=?",Boolean.class,r.id)).isTrue();assertThat(metadata(r)).isEqualTo(before);}}
 @Test void claimedVerifierAndRetainedExchangeCodeDeferFlow(){var claimed=flow(CUTOFF,"BROWSER","LOGIN","CLAIMED",false);var verifier=flow(CUTOFF,"BROWSER","LOGIN","OPEN",true);var code=exchange(CUTOFF,null,false);assertThat(sweep(Family.FLOW)).isZero();assertThat(present(claimed)).isTrue();assertThat(present(verifier)).isTrue();assertThat(owner.queryForObject("SELECT state_hash IS NOT NULL FROM external_challenge WHERE id=?",Boolean.class,code.id)).isTrue();assertThat(sweep(Family.EXCHANGE)).isEqualTo(1);assertThat(sweep(Family.FLOW)).isEqualTo(1);}
 @Test void consumedRecentAndParentVerifierOrderingAreConservative(){var old=exchange(CUTOFF,CUTOFF,false);var recent=exchange(CUTOFF,CUTOFF.plusMillis(1),false);var source=exchange(CUTOFF,null,true);assertThat(sweep(Family.EXCHANGE)).isEqualTo(1);assertThat(present(old)).isFalse();assertThat(present(recent)).isTrue();assertThat(present(source)).isTrue();owner.update("UPDATE external_challenge SET encrypted_verifier=NULL WHERE id=?",source.id);assertThat(sweep(Family.EXCHANGE)).isEqualTo(1);}
 @Test void unfinishedRecentAndEncryptedRecoverySourceDefer(){var unfinished=recovery(CUTOFF,"EVIDENCE_REVIEW",CUTOFF,false);var recent=recovery(CUTOFF,"COMPLETED",CUTOFF.plusMillis(1),false);var source=recovery(CUTOFF,"NOTICE_PERIOD",CUTOFF,true);assertThat(sweep(Family.RECOVERY)).isZero();for(var r:List.of(unfinished,recent,source))assertThat(present(r)).isTrue();owner.update("UPDATE recovery_delivery SET encrypted_token=NULL WHERE case_id=?",source.id);assertThat(sweep(Family.RECOVERY)).isEqualTo(1);}
 @Test void uncertainRecoverySendDefersUntilDefiniteOutcome(){var r=row(Family.RECOVERY,CUTOFF);UUID delivery=owner.queryForObject("SELECT id FROM recovery_delivery WHERE case_id=?",UUID.class,r.id),job=IDS.next();owner.update("INSERT INTO external_fanout(source_kind,source_id,created_at) VALUES('RECOVERY',?,?)",delivery,at(NOW));owner.update("INSERT INTO external_job(id,source_kind,source_id,channel,state,next_attempt_at,terminal_at,created_at) VALUES(?,'RECOVERY',?,'EMAIL','UNKNOWN',?,?,?)",job,delivery,at(NOW),at(NOW),at(NOW));assertThat(sweep(Family.RECOVERY)).isZero();owner.update("UPDATE external_job SET state='DELIVERED' WHERE id=?",job);assertThat(sweep(Family.RECOVERY)).isEqualTo(1);}
 @Test void restoreMixedUpdateInitialRetirementAndDeleteRemainDenied(){for(Family f:Family.values()){var r=row(f,CUTOFF);String table=table(f),key=key(f),field=field(f);assertThatThrownBy(()->owner.update("UPDATE "+table+" SET "+field+"=NULL,"+key+"=? WHERE "+key+"=?",IDS.next(),r.id)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(sweep(f)).isEqualTo(1);assertThatThrownBy(()->owner.update("UPDATE "+table+" SET "+field+"=? WHERE "+key+"=?",hash(IDS.next()),r.id)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->owner.update("DELETE FROM "+table+" WHERE "+key+"=?",r.id)).isInstanceOf(org.springframework.dao.DataAccessException.class);if(f!=Family.RECOVERY)assertThatThrownBy(()->owner.update("INSERT INTO "+table+" SELECT(jsonb_populate_record(NULL::"+table+",to_jsonb(p))).* FROM "+table+" p WHERE "+key+"=?",r.id)).hasStackTraceContaining("Initial proof secret required");else{assertThatThrownBy(()->owner.update("UPDATE recovery_case SET acceptance_retired=false WHERE id=?",r.id)).hasStackTraceContaining("Retired recovery acceptance is immutable");assertThatThrownBy(()->owner.update("INSERT INTO recovery_case SELECT(jsonb_populate_record(NULL::recovery_case,to_jsonb(p))).* FROM recovery_case p WHERE id=?",r.id)).hasStackTraceContaining("Initial recovery acceptance cannot be retired");}if(f==Family.EXCHANGE)sweep(Family.FLOW);}}
 @Test void retiredRowsCannotConsumeOrProduceFreshExchanges(){var e=row(Family.EXCHANGE,CUTOFF);var f=row(Family.FLOW,CUTOFF);var r=row(Family.RECOVERY,CUTOFF);sweep(Family.EXCHANGE);sweep(Family.FLOW);sweep(Family.RECOVERY);assertThatThrownBy(()->owner.update("UPDATE external_exchange SET consumed_at=? WHERE challenge_id=?",at(NOW),e.id)).hasStackTraceContaining("Retired exchange cannot be consumed");assertThatThrownBy(()->owner.update("UPDATE external_challenge SET state='CLAIMED' WHERE id=?",f.id)).hasStackTraceContaining("Retired proof cannot be consumed");assertThatThrownBy(()->owner.update("UPDATE recovery_case SET state='COMPLETED',consumed_at=?,revision=revision+1,updated_at=? WHERE id=?",at(NOW),at(NOW),r.id)).hasStackTraceContaining("Retired recovery acceptance is immutable");assertThatThrownBy(()->owner.update("INSERT INTO external_exchange(code_hash,challenge_id,account_id,issuer,subject,security_epoch,credential_generation,authenticated_at,expires_at) VALUES(?,?,?,'https://synthetic.example','synthetic-subject',0,0,?,?)",hash(IDS.next()),f.id,admin,at(NOW),at(NOW.plusSeconds(60)))).hasStackTraceContaining("Live native exchange bindings required");}
 @Test void twoWorkersSkipLockedTargetsAcrossAllThreeFamilies()throws Exception{var held=new ArrayList<Row>();var free=new ArrayList<Row>();for(Family f:Family.values()){held.add(row(f,CUTOFF));free.add(row(f,CUTOFF));}try(var c=owner.getDataSource().getConnection()){c.setAutoCommit(false);for(var r:held)try(var q=c.prepareStatement("SELECT "+key(r.family)+" FROM "+table(r.family)+" WHERE "+key(r.family)+"=? FOR UPDATE")){q.setObject(1,r.id);q.execute();}try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->Arrays.stream(Family.values()).mapToInt(this::sweep).sum());var b=pool.submit(()->Arrays.stream(Family.values()).mapToInt(this::sweep).sum());assertThat(a.get(10,TimeUnit.SECONDS)+b.get(10,TimeUnit.SECONDS)).isEqualTo(4);}for(var r:held)assertThat(present(r)).isTrue();for(var r:free)assertThat(present(r)).isFalse();c.rollback();}for(Family f:Family.values())assertThat(sweep(f)).isEqualTo(f==Family.FLOW?2:1);}
 @Test void oneThousandFlowBoundConvergesWithoutDeletingSources(){var ids=owner.queryForList("INSERT INTO external_challenge(id,state_hash,provider,purpose,transport,return_target,browser_binding_hash,encrypted_verifier,state,created_at,expires_at) SELECT id,decode(md5(id::text)||md5(id::text),'hex'),'GOOGLE','LOGIN','BROWSER','WEB',decode(repeat('11',32),'hex'),decode(repeat('11',71),'hex'),'OPEN',?,? FROM(SELECT gen_random_uuid() AS id FROM generate_series(1,1006)) x RETURNING id",UUID.class,at(CUTOFF.minusSeconds(300)),at(CUTOFF));owner.update("UPDATE external_challenge SET encrypted_verifier=NULL WHERE id=ANY(?)",(Object)ids.toArray(UUID[]::new));assertThat(sweep(Family.FLOW)).isEqualTo(1000);assertThat(sweep(Family.FLOW)).isEqualTo(6);assertThat(owner.queryForObject("SELECT count(*) FROM external_challenge WHERE id=ANY(?)",Integer.class,(Object)ids.toArray(UUID[]::new))).isEqualTo(1006);}
 @Test void oneThousandExchangeBoundPreservesEveryOriginalChallenge(){var ids=owner.queryForList("INSERT INTO external_challenge(id,state_hash,provider,purpose,transport,return_target,native_challenge,encrypted_verifier,state,created_at,expires_at) SELECT id,decode(md5(id::text)||md5(id::text),'hex'),'GOOGLE','LOGIN','NATIVE','ANDROID',repeat('a',43),decode(repeat('11',71),'hex'),'COMPLETED',?,? FROM(SELECT gen_random_uuid() AS id FROM generate_series(1,1006)) x RETURNING id",UUID.class,at(CUTOFF.minusSeconds(300)),at(CUTOFF));owner.update("INSERT INTO external_exchange(code_hash,challenge_id,account_id,issuer,subject,security_epoch,credential_generation,authenticated_at,expires_at) SELECT decode(md5(id::text)||md5(id::text),'hex'),id,?,'https://synthetic.example','synthetic',0,0,?,? FROM external_challenge WHERE id=ANY(?)",admin,at(CUTOFF.minusSeconds(60)),at(CUTOFF),(Object)ids.toArray(UUID[]::new));owner.update("UPDATE external_challenge SET encrypted_verifier=NULL WHERE id=ANY(?)",(Object)ids.toArray(UUID[]::new));assertThat(sweep(Family.EXCHANGE)).isEqualTo(1000);assertThat(sweep(Family.EXCHANGE)).isEqualTo(6);assertThat(owner.queryForObject("SELECT count(*) FROM external_exchange WHERE challenge_id=ANY(?)",Integer.class,(Object)ids.toArray(UUID[]::new))).isEqualTo(1006);}
 @Test void oneThousandRecoveryBoundPreservesCasesAndRevisions(){var ids=owner.queryForList("INSERT INTO recovery_case(id,creator_id,creator_epoch,reviewer_id,reviewer_epoch,organization_id,target_id,former_owner_id,target_epoch,target_generation,owner_epoch,owner_generation,kind,old_email,new_email,reason,evidence_reference,request_digest,state,token_hash,created_at,not_before,expires_at,updated_at) SELECT id,?,0,?,0,?,?,?,0,0,0,0,'EMAIL','synthetic-before@example.com',id::text||'@example.com','Synthetic','synthetic/evidence',decode(md5(id::text)||md5(id::text),'hex'),'NOTICE_PERIOD',decode(md5(id::text)||md5(id::text),'hex'),?,?,?,? FROM(SELECT gen_random_uuid() AS id FROM generate_series(1,1006)) x RETURNING id",UUID.class,admin,reviewer,org,business,business,at(CUTOFF.minusSeconds(8*86400)),at(CUTOFF.minusSeconds(7*86400)),at(CUTOFF),at(CUTOFF));assertThat(sweep(Family.RECOVERY)).isEqualTo(1000);assertThat(sweep(Family.RECOVERY)).isEqualTo(6);assertThat(owner.queryForObject("SELECT count(*) FROM recovery_case WHERE id=ANY(?) AND revision=1 AND acceptance_retired",Integer.class,(Object)ids.toArray(UUID[]::new))).isEqualTo(1006);}
 @Test void statementFailureAfterTwoWritesRollsBackBothCodesAndRetryConverges(){Row a=row(Family.EXCHANGE,CUTOFF),b=row(Family.EXCHANGE,CUTOFF);owner.execute("CREATE SEQUENCE capability_rollback_probe");owner.execute("CREATE FUNCTION capability_probe_row() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN PERFORM nextval('public.capability_rollback_probe');RETURN NEW;END $$");owner.execute("CREATE FUNCTION capability_fail_statement() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Synthetic post-write failure';END $$");owner.execute("CREATE TRIGGER tr_capability_probe AFTER UPDATE ON external_exchange FOR EACH ROW EXECUTE FUNCTION capability_probe_row()");owner.execute("CREATE TRIGGER tr_capability_failure AFTER UPDATE ON external_exchange FOR EACH STATEMENT EXECUTE FUNCTION capability_fail_statement()");try{assertThatThrownBy(()->sweep(Family.EXCHANGE)).hasStackTraceContaining("Synthetic post-write failure");assertThat(owner.queryForObject("SELECT last_value FROM capability_rollback_probe",Long.class)).isEqualTo(2);assertThat(present(a)).isTrue();assertThat(present(b)).isTrue();}finally{owner.execute("DROP TRIGGER tr_capability_probe ON external_exchange");owner.execute("DROP TRIGGER tr_capability_failure ON external_exchange");owner.execute("DROP FUNCTION capability_probe_row()");owner.execute("DROP FUNCTION capability_fail_statement()");owner.execute("DROP SEQUENCE capability_rollback_probe");}assertThat(sweep(Family.EXCHANGE)).isEqualTo(2);}
 @Test void aggregatePreviewIsReadOnlyAndRuntimeCannotRewriteHistory()throws Exception{for(Family f:Family.values())row(f,CUTOFF);var limited=new JdbcTemplate(runtime);assertThatThrownBy(()->limited.update("DELETE FROM external_exchange")).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->limited.update("UPDATE recovery_case SET reason='Changed'")).isInstanceOf(org.springframework.dao.DataAccessException.class);var counts=new TreeMap<String,Long>();try(var c=runtime.getConnection();var q=c.createStatement()){q.execute(Files.readString(Path.of("retention/capability-preview.sql")));do{if(q.getResultSet()!=null){var r=q.getResultSet();while(r.next())counts.put(r.getString("family"),r.getLong("eligible_secrets"));}}while(q.getMoreResults()||q.getUpdateCount()!=-1);}assertThat(counts).containsEntry("exchange",1L).containsEntry("flow",1L).containsEntry("recovery",1L);}
 @Test void verifierRetirementWinsConcurrentExchangeInsertionAfterRealRowWait()throws Exception{
  var f=flow(CUTOFF,"NATIVE","LOGIN","COMPLETED",true);
  try(var c=owner.getDataSource().getConnection()){c.setAutoCommit(false);int pid;try(var q=c.createStatement();var r=q.executeQuery("SELECT pg_backend_pid()")){r.next();pid=r.getInt(1);}try(var q=c.prepareStatement("UPDATE external_challenge SET encrypted_verifier=NULL WHERE id=?")){q.setObject(1,f.id);q.executeUpdate();}
   try(var pool=Executors.newSingleThreadExecutor()){var result=pool.submit(()->{try{owner.update("INSERT INTO external_exchange(code_hash,challenge_id,account_id,issuer,subject,security_epoch,credential_generation,authenticated_at,expires_at) VALUES(?,?,?,'https://synthetic.example','synthetic',0,0,?,?)",hash(IDS.next()),f.id,admin,at(CUTOFF.minusSeconds(60)),at(CUTOFF));return (Throwable)null;}catch(org.springframework.dao.DataAccessException failure){return failure;}});boolean waiting=false;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(4);while(System.nanoTime()<deadline){if(owner.queryForObject("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE ?=ANY(pg_blocking_pids(pid)))",Boolean.class,pid)){waiting=true;break;}}if(!waiting)c.rollback();assertThat(waiting).as("exchange initial guard waits on the parent verifier retirement").isTrue();c.commit();assertThat(result.get(10,TimeUnit.SECONDS)).isInstanceOf(org.springframework.dao.DataAccessException.class).hasStackTraceContaining("Live native exchange bindings required");}
  }assertThat(owner.queryForObject("SELECT count(*) FROM external_exchange WHERE challenge_id=?",Integer.class,f.id)).isZero();
 }
}
